package dev.srpbackport.tests;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
import io.netty.buffer.*;import cpw.mods.fml.common.*;import cpw.mods.fml.common.event.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;import cpw.mods.fml.common.registry.EntityRegistry;
import cpw.mods.fml.common.network.internal.FMLProxyPacket;import net.minecraft.entity.Entity;import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.nbt.NBTTagCompound;
import com.dhanantry.scapeandrunparasites.backport.datasync.*;import com.dhanantry.scapeandrunparasites.backport.math.BlockPos;import com.dhanantry.scapeandrunparasites.backport.entity.LegacyEntity;
@Mod(modid="srp_datasync_checks",name="Disposable entity tracked-data checks",version="1")
public final class NativeEntityDataChecks {
 public static class Probe extends LegacyEntity {
  public static final DataParameter<Byte> SKIN=EntityDataManager.createKey(Probe.class,DataSerializers.BYTE);
  public static final DataParameter<Integer> ANIMATION=EntityDataManager.createKey(Probe.class,DataSerializers.VARINT);
  public static final DataParameter<Float> SIZE=EntityDataManager.createKey(Probe.class,DataSerializers.FLOAT);
  public static final DataParameter<Boolean> ACTIVE=EntityDataManager.createKey(Probe.class,DataSerializers.BOOLEAN);
  public static final DataParameter<BlockPos> TARGET=EntityDataManager.createKey(Probe.class,DataSerializers.BLOCK_POS);
  int callbacks,animationMirror=-1;Thread callbackThread;
  public Probe(World world){super(world);setSize(0.5f,1);setPosition(0,85,0);}
  @Override protected void entityInit(){EntityDataManager d=EntityDataManager.of(this);d.register(SKIN,(Object)0);d.register(ANIMATION,0);d.register(SIZE,1.0f);d.register(ACTIVE,false);d.register(TARGET,BlockPos.ORIGIN);}
  @Override public void notifyDataManagerChange(DataParameter<?> key){callbacks++;callbackThread=Thread.currentThread();if(key.equals(ANIMATION))animationMirror=EntityDataManager.of(this).get(ANIMATION);super.notifyDataManagerChange(key);}
  protected void writeEntityToNBT(NBTTagCompound n){EntityDataManager d=EntityDataManager.of(this);n.setByte("skin",d.get(SKIN));n.setInteger("animation",d.get(ANIMATION));n.setFloat("size",d.get(SIZE));n.setBoolean("active",d.get(ACTIVE));n.setLong("target",d.get(TARGET).toLong());}
  protected void readEntityFromNBT(NBTTagCompound n){EntityDataManager d=EntityDataManager.of(this);d.set(SKIN,n.getByte("skin"));d.set(ANIMATION,n.getInteger("animation"));d.set(SIZE,n.getFloat("size"));d.set(ACTIVE,n.getBoolean("active"));d.set(TARGET,BlockPos.fromLong(n.getLong("target")));}
  int vanillaWatched(){return dataWatcher.getAllWatched().size();}byte vanillaFlags(){return dataWatcher.getWatchableObjectByte(0);}
 }
 public static final class LargeProbe extends Probe {
  @SuppressWarnings("unchecked") static final DataParameter<Integer>[] EXTRA=new DataParameter[100];
  static{for(int i=0;i<EXTRA.length;i++)EXTRA[i]=EntityDataManager.createKey(LargeProbe.class,DataSerializers.VARINT);}
  public LargeProbe(World world){super(world);}
  @Override protected void entityInit(){super.entityInit();for(int i=0;i<EXTRA.length;i++)EntityDataManager.of(this).register(EXTRA[i],i);}
 }
 private final List<String> report=new ArrayList<String>();private WorldServer world;private int ticks,failed,assertions;private boolean done;
 @Mod.EventHandler public void preInit(FMLPreInitializationEvent e){NativeEntityDataSync.initialize();EntityRegistry.registerModEntity(Probe.class,"probe",1,this,64,1,true);EntityRegistry.registerModEntity(LargeProbe.class,"large_probe",2,this,64,1,true);}
 @Mod.EventHandler public void init(FMLInitializationEvent e){FMLCommonHandler.instance().bus().register(this);if(Boolean.getBoolean("srp.datasyncClientTest")&&FMLCommonHandler.instance().getSide().isClient())try{Class.forName("dev.srpbackport.tests.NativeEntityDataClientChecks").getMethod("initialize").invoke(null);}catch(ReflectiveOperationException ex){throw new RuntimeException(ex);}}
 interface Check{void run()throws Exception;}void check(boolean value,String why){assertions++;if(!value)throw new AssertionError(why);}void test(String name,Check body){try{body.run();report.add("PASS: "+name);}catch(Throwable e){failed++;report.add("FAIL: "+name+" :: "+e);e.printStackTrace();}}
 Probe spawn(){Probe actor=new Probe(world);check(world.spawnEntityInWorld(actor),"Native actor spawn");return actor;}
 EntityDataPacket message(Probe source,int targetId,int kind,List<EntityDataManager.DataEntry<?>> values){EntityDataPacket p=new EntityDataPacket(source,EntityDataManager.of(source),kind,values);p.entityId=targetId;return p;}
 EntityDataPacket throughForge(EntityDataPacket original){FMLProxyPacket proxy=(FMLProxyPacket)NativeEntityDataSync.packetFor(original);ByteBuf payload=proxy.payload().duplicate();check(payload.readUnsignedByte()==0,"Forge discriminator");EntityDataPacket result=new EntityDataPacket();result.fromBytes(payload);return result;}
 EntityDataPacket full(Probe source,int targetId){return throughForge(message(source,targetId,EntityDataPacket.FULL,EntityDataManager.of(source).getAll()));}
 EntityDataPacket delta(Probe source,int targetId){return throughForge(message(source,targetId,EntityDataPacket.DELTA,EntityDataManager.of(source).getDirty()));}
 void initial(){
  test("Native construction registers 105 inherited values without consuming legacy DataWatcher slots",()->{LargeProbe p=new LargeProbe(world);EntityDataManager d=EntityDataManager.of(p);check(d.getAll().size()==105&&LargeProbe.EXTRA[0].getId()>Probe.TARGET.getId(),"Inherited parameter layout");int count=p.vanillaWatched();d.set(LargeProbe.EXTRA[99],-7654321);check(d.get(LargeProbe.EXTRA[99])==-7654321&&p.vanillaWatched()==count&&p.vanillaFlags()==0,"Legacy watcher collision");check(d.get(Probe.SKIN).getClass()==Byte.class,"Recovered byte literal was boxed as Integer");});
  test("Manager identity survives native entity-ID reassignment",()->{Probe p=new Probe(world);EntityDataManager d=EntityDataManager.of(p);d.set(Probe.ANIMATION,37);p.setEntityId(987654321);check(EntityDataManager.of(p)==d&&EntityDataManager.of(p).get(Probe.ANIMATION)==37,"Mutable Entity.hashCode broke the manager cache");});
  test("Changed values trigger original callbacks once and unchanged values stay clean",()->{Probe p=new Probe(world);EntityDataManager d=EntityDataManager.of(p);d.setClean();int before=p.callbacks;d.set(Probe.ANIMATION,41);check(p.callbacks==before+1&&p.animationMirror==41&&d.isDirty(),"Missing callback");d.getDirty();d.set(Probe.ANIMATION,41);check(p.callbacks==before+1&&!d.isDirty(),"Unchanged value notified");});
  test("Invalid tracked values and duplicate registrations fail before changing state",()->{Probe p=new Probe(world);EntityDataManager d=EntityDataManager.of(p);long version=d.revision();int caught=0;try{d.set(Probe.SKIN,5);}catch(IllegalArgumentException e){caught++;}try{d.register(Probe.ANIMATION,5);}catch(IllegalArgumentException e){caught++;}try{d.get(new DataParameter<Integer>(222,DataSerializers.VARINT));}catch(IllegalArgumentException e){caught++;}check(caught==3&&d.revision()==version&&d.get(Probe.SKIN)==0,"Invalid update changed tracked state");});
  test("Genuine Forge custom-payload encoding preserves complete tracked snapshots",()->{Probe source=spawn(),mirror=spawn();EntityDataManager d=EntityDataManager.of(source);d.set(Probe.SKIN,(byte)12);d.set(Probe.ANIMATION,71);d.set(Probe.SIZE,3.25f);d.set(Probe.ACTIVE,true);d.set(Probe.TARGET,new BlockPos(-123456,77,234567));EntityDataInbox inbox=new EntityDataInbox();inbox.enqueue(full(source,mirror.getEntityId()));inbox.tick(world,(dim,id)->{});EntityDataManager r=EntityDataManager.of(mirror);check(r.get(Probe.SKIN)==12&&r.get(Probe.ANIMATION)==71&&r.get(Probe.SIZE)==3.25f&&r.get(Probe.ACTIVE)&&r.get(Probe.TARGET).equals(new BlockPos(-123456,77,234567)),"Snapshot values");check(mirror.animationMirror==71&&inbox.boundEntities()==1,"Snapshot callbacks/binding");});
  test("Network receipt defers entity callbacks until the main-thread inbox pump",()->{Probe source=spawn(),mirror=spawn();EntityDataManager.of(source).set(Probe.ANIMATION,88);EntityDataPacket packet=full(source,mirror.getEntityId());EntityDataInbox inbox=new EntityDataInbox();int before=mirror.callbacks;Thread network=new Thread(()->new NativeEntityDataSync.ClientHandler().onMessage(packet,null),"simulated-netty-receive");network.start();network.join();check(mirror.callbacks==before,"Network thread mutated entity");NativeEntityDataSync.CLIENT_INBOX.tick(world,(dim,id)->{});check(mirror.animationMirror==88&&mirror.callbackThread==Thread.currentThread(),"Callback ran outside main-thread pump");NativeEntityDataSync.CLIENT_INBOX.clear();});
  test("Deltas queued before a snapshot apply after its baseline and in revision order",()->{Probe source=spawn(),mirror=spawn();EntityDataManager d=EntityDataManager.of(source);d.set(Probe.ANIMATION,10);EntityDataPacket baseline=full(source,mirror.getEntityId());d.setClean();d.set(Probe.ANIMATION,20);EntityDataPacket first=delta(source,mirror.getEntityId());d.set(Probe.ACTIVE,true);EntityDataPacket second=delta(source,mirror.getEntityId());EntityDataInbox inbox=new EntityDataInbox();inbox.enqueue(second);inbox.enqueue(first);inbox.tick(world,(dim,id)->{});check(mirror.animationMirror==-1&&inbox.pendingEntities()==1,"Unbound delta applied");inbox.enqueue(baseline);inbox.tick(world,(dim,id)->{});check(mirror.animationMirror==20&&EntityDataManager.of(mirror).get(Probe.ACTIVE)&&inbox.pendingEntities()==0,"Delta ordering/baseline");inbox.enqueue(first);inbox.tick(world,(dim,id)->{});check(mirror.animationMirror==20,"Stale delta rewound animation");});
  test("Pre-spawn snapshots wait for a matching native entity instead of disappearing",()->{Probe source=spawn(),mirror=new Probe(world);EntityDataManager.of(source).set(Probe.ANIMATION,123);EntityDataInbox inbox=new EntityDataInbox();inbox.enqueue(full(source,mirror.getEntityId()));inbox.tick(world,(dim,id)->{});check(inbox.pendingEntities()==1&&mirror.animationMirror==-1,"Pre-spawn snapshot lost or applied early");world.spawnEntityInWorld(mirror);inbox.tick(world,(dim,id)->{});check(mirror.animationMirror==123&&inbox.pendingEntities()==0,"Delayed native spawn");});
  test("Wrong-dimension frames stay isolated and disconnect clears queued state",()->{Probe source=spawn(),mirror=spawn();EntityDataManager.of(source).set(Probe.ANIMATION,456);EntityDataPacket packet=full(source,mirror.getEntityId());packet.dimension=127;EntityDataInbox inbox=new EntityDataInbox();inbox.enqueue(packet);inbox.tick(world,(dim,id)->{});check(mirror.animationMirror==-1&&inbox.pendingEntities()==1,"Wrong dimension applied");inbox.clear();check(inbox.pendingEntities()==0&&inbox.boundEntities()==0,"Disconnect state retained");});
  test("Missing snapshots request resync on the main thread with per-entity throttling",()->{Probe mirror=spawn();EntityDataInbox inbox=new EntityDataInbox();List<Integer> sent=new ArrayList<Integer>();EntityDataInbox.RequestSender sink=(dim,id)->{if(id==mirror.getEntityId())sent.add(id);};inbox.tick(world,sink);for(int i=0;i<39;i++)inbox.tick(world,sink);check(sent.size()==1,"Resync request not throttled");inbox.tick(world,sink);check(sent.size()==2,"Resync request not retried");});
  test("Remote serializer mismatch is rejected before any partial entity update",()->{Probe mirror=spawn();EntityDataManager d=EntityDataManager.of(mirror);List<EntityDataManager.DataEntry<?>> entries=new ArrayList<EntityDataManager.DataEntry<?>>();entries.add(new EntityDataManager.DataEntry<Integer>(Probe.ANIMATION,987));entries.add(new EntityDataManager.DataEntry<Integer>(new DataParameter<Integer>(Probe.SKIN.getId(),DataSerializers.VARINT),8));boolean rejected=false;try{d.setEntryValues(entries);}catch(IllegalArgumentException expected){rejected=true;}check(rejected&&d.get(Probe.ANIMATION)==0&&mirror.callbacks==0,"Partial corrupt update");});
  test("Native entity NBT persists all five tracked value types to an actual chunk",()->{Probe p=spawn();p.setPosition(20,85,20);EntityDataManager d=EntityDataManager.of(p);d.set(Probe.SKIN,(byte)7);d.set(Probe.ANIMATION,7123);d.set(Probe.SIZE,2.5f);d.set(Probe.ACTIVE,true);d.set(Probe.TARGET,new BlockPos(-42,72,1337));world.saveAllChunks(true,null);Files.write(Paths.get("datasync-saved.done"),Arrays.asList("tracked actor saved"),StandardCharsets.UTF_8);});
 }
 void restart(){test("Tracked entity values and callback-derived animation survive a genuine JVM restart",()->{Probe saved=null;for(Object o:world.loadedEntityList)if(o instanceof Probe&&((Probe)o).posX==20&&((Probe)o).posZ==20){saved=(Probe)o;break;}check(saved!=null,"Saved native actor missing");EntityDataManager d=EntityDataManager.of(saved);check(d.get(Probe.SKIN)==7&&d.get(Probe.ANIMATION)==7123&&d.get(Probe.SIZE)==2.5f&&d.get(Probe.ACTIVE)&&d.get(Probe.TARGET).equals(new BlockPos(-42,72,1337))&&saved.animationMirror==7123,"Tracked NBT reload/callbacks");});}
 @SubscribeEvent public void tick(TickEvent.ServerTickEvent event){if(Boolean.getBoolean("srp.datasyncClientTest")||done||event.phase!=TickEvent.Phase.END||++ticks!=20)return;String phase=Files.exists(Paths.get("datasync-saved.done"))?"restart":"initial";try{world=MinecraftServer.getServer().worldServerForDimension(0);world.getChunkFromChunkCoords(0,0);world.getChunkFromChunkCoords(1,1);if(phase.equals("initial"))initial();else restart();}catch(Throwable e){failed++;report.add("FAIL: setup :: "+e);e.printStackTrace();}finally{done=true;report.add("Assertions: "+assertions);report.add("Failed: "+failed);try{Files.write(Paths.get("datasync-"+phase+".txt"),report,StandardCharsets.UTF_8);}catch(IOException e){throw new RuntimeException(e);}MinecraftServer.getServer().initiateShutdown();}}
}
